import{_ as p,D as l,o as e,c as t,j as n,a as s,I as i,w as c,am as d}from"./chunks/framework.DXw8qDd0.js";const E=JSON.parse('{"title":"AGENTS.md实战手册","description":"","frontmatter":{"title":"AGENTS.md实战手册","time":"2026-06-07T00:00:00.000Z","tags":["codex"]},"headers":[],"relativePath":"笔记/Codex/AGENTS.md实战手册.md","filePath":"笔记/Codex/AGENTS.md实战手册.md"}'),o={name:"笔记/Codex/AGENTS.md实战手册.md"},r=d(`<h1 id="agents-md-实战手册" tabindex="-1">AGENTS.md 实战手册 <a class="header-anchor" href="#agents-md-实战手册" aria-label="Permalink to &quot;AGENTS.md 实战手册&quot;">​</a></h1><hr><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><p>每开启一个新的 Codex 对话窗口，它都会进入一个全新的上下文。它不记得之前发生了什么，对于整个项目的记忆都是空白的。</p><p>AGENTS.md 就是 Codex 的记忆系统——你在对话开始前写好的项目说明书。Codex 开始工作之前会先读取 AGENTS.md 的内容，把它自动带入到新的对话中，作为它的上下文。</p><p>没有项目规则时，Codex 每次都要从仓库里推断：用哪个包管理器、如何运行测试、哪些目录是生成物、哪些文件不能改、提交前要跑哪些检查。把这些规则显式写下来，可以大幅减少重复解释和误操作。</p><hr><h2 id="作用域与层级" tabindex="-1">作用域与层级 <a class="header-anchor" href="#作用域与层级" aria-label="Permalink to &quot;作用域与层级&quot;">​</a></h2><p>AGENTS.md 的作用域是从它所在的目录开始，向下覆盖所有子目录。换句话说，放在项目根目录的 AGENTS.md 会覆盖整个项目。</p><p>如果在子目录下也创建了 AGENTS.md，那么更深一层的 AGENTS.md 会覆盖上层的同名指令（在它自己的范围内）。这一点非常重要——你可以用这个机制为不同模块写不同的规则。</p><p>层级优先级（从高到低）：</p><ol><li>当前目录及其子目录中的 AGENTS.md（最深的优先）</li><li>上层目录中的 AGENTS.md</li><li>项目根目录中的 AGENTS.md</li><li>全局 AGENTS.md（Codex 桌面 App 设置中的「自定义指令」）</li></ol><p>如果出现冲突：更深层的 AGENTS.md 指令优先；系统/开发者直接指令（prompt 中的）优先于 AGENTS.md。</p><hr><h2 id="项目级-vs-全局级" tabindex="-1">项目级 vs 全局级 <a class="header-anchor" href="#项目级-vs-全局级" aria-label="Permalink to &quot;项目级 vs 全局级&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>项目级 AGENTS.md</th><th>全局级（桌面 App 自定义指令）</th></tr></thead><tbody><tr><td>放在哪</td><td>项目根目录或子目录</td><td>Codex 桌面 App &gt; 设置 &gt; 个性化 &gt; 自定义指令</td></tr><tr><td>谁能看到</td><td>团队所有成员（提交到仓库）</td><td>只有你自己的所有项目</td></tr><tr><td>适合写什么</td><td>项目命令、代码规范、目录说明、禁止事项、验证要求</td><td>个人偏好、通用习惯、模型选择、语言风格</td></tr><tr><td>不适合写什么</td><td>个人密钥、token、私有服务地址</td><td>项目特定的命令和目录说明</td></tr></tbody></table><p>原则：项目共同规则写进 AGENTS.md 进仓库；个人偏好留在本机全局配置。</p><hr><h2 id="与-config-toml-的分工" tabindex="-1">与 config.toml 的分工 <a class="header-anchor" href="#与-config-toml-的分工" aria-label="Permalink to &quot;与 config.toml 的分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>放在哪</th><th>适合放什么</th></tr></thead><tbody><tr><td>AGENTS.md（进仓库）</td><td>推荐测试命令、代码风格和目录说明、PR 模板、文档截图规范、禁止事项</td></tr><tr><td>config.toml（留在本机）</td><td>默认模型偏好、本地路径、凭证、密钥、私有服务地址、个人 MCP 服务、私有 automation 配置</td></tr></tbody></table><p>简单说：共享的项目规范放 AGENTS.md，个人的 CLI 偏好放 config.toml。</p><hr><h2 id="写作原则" tabindex="-1">写作原则 <a class="header-anchor" href="#写作原则" aria-label="Permalink to &quot;写作原则&quot;">​</a></h2><ul><li>越具体越好。「运行测试：pnpm test」比「记得测试」有用。</li><li>把生成目录、构建产物、锁文件策略写清楚。</li><li>如果是 monorepo，请说明每个包的边界。</li><li>如果有特殊 lint、格式化或代码生成流程，写在命令区。</li><li>对安全敏感项目，单独写「禁止事项」。</li><li>安全敏感项不要写进教程截图。</li></ul><hr><h2 id="完整模板-适合中型项目" tabindex="-1">完整模板（适合中型项目） <a class="header-anchor" href="#完整模板-适合中型项目" aria-label="Permalink to &quot;完整模板（适合中型项目）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span># AGENTS.md</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 项目概览</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 项目类型：Web 应用</span></span>
<span class="line"><span>- 主要语言：TypeScript</span></span>
<span class="line"><span>- 包管理器：pnpm</span></span>
<span class="line"><span>- 关键目录：</span></span>
<span class="line"><span>  - src/：业务代码</span></span>
<span class="line"><span>  - src/components/：UI 组件</span></span>
<span class="line"><span>  - src/utils/：工具函数</span></span>
<span class="line"><span>  - tests/：测试文件</span></span>
<span class="line"><span>  - docs/：文档</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 常用命令</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 安装依赖：pnpm install</span></span>
<span class="line"><span>- 本地开发：pnpm dev</span></span>
<span class="line"><span>- 构建：pnpm build</span></span>
<span class="line"><span>- 运行测试：pnpm test</span></span>
<span class="line"><span>- 运行单个测试文件：pnpm test -- tests/parser.test.ts</span></span>
<span class="line"><span>- 类型检查：pnpm tsc --noEmit</span></span>
<span class="line"><span>- 格式化：pnpm format</span></span>
<span class="line"><span>- Lint：pnpm lint</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 代码规范</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 遵循现有代码风格，不混用多种风格。</span></span>
<span class="line"><span>- 不做无关重构，除非任务明确要求。</span></span>
<span class="line"><span>- 新增功能必须补充或更新测试。</span></span>
<span class="line"><span>- 组件使用 PascalCase，工具函数使用 camelCase。</span></span>
<span class="line"><span>- 文件名使用 kebab-case。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 目录说明</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- src/components/ 下的文件是一一对应的组件和测试。</span></span>
<span class="line"><span>- tests/ 下是集成测试。</span></span>
<span class="line"><span>- docs/ 下的改动需要运行 pnpm build 验证。</span></span>
<span class="line"><span>- dist/ 和 node_modules/ 是生成物，不要手动修改。</span></span>
<span class="line"><span>- .env 和 .env.local 包含敏感配置，不要读取或提交。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 改动规则</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 修改前先阅读相关文件和测试。</span></span>
<span class="line"><span>- 保持现有代码风格和目录结构。</span></span>
<span class="line"><span>- 不引入新的外部依赖，除非任务明确要求。</span></span>
<span class="line"><span>- 不修改数据库 schema 或迁移文件，除非任务明确要求。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 安全边界</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 不读取或提交 .env、密钥、token 或任何私有凭证。</span></span>
<span class="line"><span>- 不执行删除生产数据的命令。</span></span>
<span class="line"><span>- 不执行发布、部署、数据库迁移命令，除非我明确认。</span></span>
<span class="line"><span>- 修改认证、权限、支付逻辑前先说明影响。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 验证要求</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 文档改动运行：pnpm build</span></span>
<span class="line"><span>- 代码改动运行相关测试。</span></span>
<span class="line"><span>- 提交前确认没有新增 lint 错误。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 交付要求</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 说明改动了哪些文件。</span></span>
<span class="line"><span>- 说明验证命令和结果。</span></span>
<span class="line"><span>- 说明未验证项和剩余风险。</span></span></code></pre></div><hr><h2 id="最小模板-适合小项目或刚上手" tabindex="-1">最小模板（适合小项目或刚上手） <a class="header-anchor" href="#最小模板-适合小项目或刚上手" aria-label="Permalink to &quot;最小模板（适合小项目或刚上手）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span># AGENTS.md</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 项目命令</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 安装依赖：pnpm install</span></span>
<span class="line"><span>- 本地开发：pnpm dev</span></span>
<span class="line"><span>- 构建：pnpm build</span></span>
<span class="line"><span>- 测试：pnpm test</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 改动规则</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 修改前先阅读相关文件。</span></span>
<span class="line"><span>- 保持现有代码风格。</span></span>
<span class="line"><span>- 不提交构建产物和环境变量文件。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 安全边界</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 不读取 .env 或任何私有凭证。</span></span>
<span class="line"><span>- 不执行发布、部署、数据库迁移和删除数据命令。</span></span></code></pre></div><hr><h2 id="monorepo-写法" tabindex="-1">Monorepo 写法 <a class="header-anchor" href="#monorepo-写法" aria-label="Permalink to &quot;Monorepo 写法&quot;">​</a></h2><p>如果是 monorepo，建议在根目录的 AGENTS.md 写全局规则，然后在每个包下放自己的 AGENTS.md 写包级规则。</p><p>根目录 AGENTS.md：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span># AGENTS.md</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 项目概览</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 这是一个 pnpm monorepo，包含以下包：</span></span>
<span class="line"><span>  - packages/core：核心逻辑</span></span>
<span class="line"><span>  - packages/ui：UI 组件库</span></span>
<span class="line"><span>  - apps/web：Web 应用</span></span>
<span class="line"><span>  - apps/admin：管理后台</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 全局命令</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 安装依赖：pnpm install（根目录执行）</span></span>
<span class="line"><span>- 构建所有包：pnpm build</span></span>
<span class="line"><span>- 运行所有测试：pnpm test</span></span>
<span class="line"><span>- 清理构建产物：pnpm clean</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 全局规则</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 不要在包之间引入循环依赖。</span></span>
<span class="line"><span>- 修改 packages/core 后，检查 apps/web 和 apps/admin 是否受影响。</span></span>
<span class="line"><span>- 不修改 pnpm-lock.yaml，除非你确定需要。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 安全边界</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 不读取 .env 或任何私有凭证。</span></span>
<span class="line"><span>- 不执行发布、部署和删除数据命令。</span></span></code></pre></div><p>packages/core/AGENTS.md：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span># packages/core AGENTS.md</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 这个包做什么</span></span>
<span class="line"><span></span></span>
<span class="line"><span>核心业务逻辑，被 apps/web 和 apps/admin 依赖。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 常用命令</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 测试：pnpm --filter @myapp/core test</span></span>
<span class="line"><span>- 类型检查：pnpm --filter @myapp/core tsc --noEmit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 改动规则</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 这个包是共享的，修改后必须确保所有消费方的测试通过。</span></span>
<span class="line"><span>- 不要在这个包里引入 UI 相关的依赖。</span></span></code></pre></div><hr><h2 id="排障清单" tabindex="-1">排障清单 <a class="header-anchor" href="#排障清单" aria-label="Permalink to &quot;排障清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>检查</th></tr></thead><tbody><tr><td>AGENTS.md 没生效</td><td>文件名是否正确（大小写）、文件编码是否 UTF-8、是否在正确目录下</td></tr><tr><td>Codex 忽略了某条规则</td><td>规则是否太模糊、是否与更深层的 AGENTS.md 冲突</td></tr><tr><td>不同模块需要不同规则</td><td>在子目录下放一个局部 AGENTS.md 覆盖上层规则</td></tr><tr><td>团队成员行为不一致</td><td>把项目共同规则写进 AGENTS.md 并提交到仓库</td></tr><tr><td>个人偏好影响了团队</td><td>把个人偏好移到全局自定义指令，不要放在项目 AGENTS.md 里</td></tr></tbody></table><hr>`,41);function m(h,b,u,T,N,A){const a=l("VPNolebaseInlineLinkPreview");return e(),t("div",null,[r,n("blockquote",null,[n("p",null,[s("📎 "),i(a,{href:"/ocdsync/笔记/"},{default:c(()=>[s("📒 返回笔记索引")]),_:1})])])])}const g=p(o,[["render",m]]);export{E as __pageData,g as default};
